mapper.select:
select ID, FACTORY_CODE, MACHINE_RANGE, MACHINE_COUNT, SHIFT_COUNT, REMARK,
       CREATE_BY, CREATE_TIME, UPDATE_BY, UPDATE_TIME
from T_TQ_STOCK_SHIFT_CONFIG

    IS_DELETE = 0
    and FACTORY_CODE = #{factoryCode}
    and MACHINE_RANGE = #{machineRange}
    and MACHINE_COUNT = #{machineCount}

order by FACTORY_CODE, MACHINE_COUNT desc
